.libPaths(c(file.path(b,'TB_metabolome_exposome_20261115_2130/analysis_MWAS_ExWAS/Rlib'),.libPaths()));library(ggplot2);library(patchwork);library(cowplot)
blue<-'#0072B2';orange<-'#D55E00';grey<-'#A5ADB4';ink<-'#263746'
