savefig<-function(fig,name,w,h){for(ex in c('svg','pdf','png'))ggsave(file.path(o,'Figures',paste0(name,'.',ex)),fig,width=w,height=h,dpi=600,bg='white',device=if(ex=='pdf')function(filename,width,height,...)quartz(type='pdf',file=filename,width=width,height=height,family='Arial')else ex);ggsave(file.path(o,'Figures',paste0(name,'_preview.png')),fig,width=w,height=h,dpi=200,bg='white')}
arc<-function(a1,a2,r1,r2,id){aa<-seq(a1,a2,length.out=max(7,ceiling(abs(a1-a2)*90)));data.frame(x=c(r1*cos(aa),r2*cos(rev(aa))),y=c(r1*sin(aa),r2*sin(rev(aa))),id=id)}
colour<-function(v,m)scales::col_numeric(c(blue,'white',orange),domain=c(-m,m))(v)
# Figure 1: four-state counts and measured nutritional context, with no candidate-specific forest.
states<-c('Q−T−','Q+T−','Q−T+','Q+T+');st<-data.frame(state=rep(states,2),domain=rep(c('Paired tests','Fatty acid weights'),each=4),n=c(3609,202,196,208,1704,83,98,94));st$state<-factor(st$state,levels=states);st$domain<-factor(st$domain,levels=c('Paired tests','Fatty acid weights'));st$prop<-ave(st$n,st$domain,FUN=function(z)z/sum(z));st<-st[order(st$domain,st$state),];st$mid<-ave(st$prop,st$domain,FUN=function(z)cumsum(z)-z/2)
ps<-ggplot(st,aes(prop,domain,fill=state))+geom_col(width=.52,position=position_stack(reverse=TRUE),colour='white',linewidth=.25)+scale_fill_manual(values=c('#D7DEE3',blue,orange,'#4B5965'),labels=c('Q−T−\n3609 / 1704','Q+T−\n202 / 83','Q−T+\n196 / 98','Q+T+\n208 / 94'),drop=FALSE)+scale_x_continuous(limits=c(0,1),breaks=c(0,.5,1),labels=scales::label_percent())+labs(x='Within-domain percentage',y=NULL,fill=NULL)+theme(axis.line.y=element_blank(),axis.ticks.y=element_blank(),legend.text=element_text(size=7),legend.margin=margin(0,0,0,0))
ggsave(file.path(o,'Figures/Figure1_B_states.svg'),ps,width=4.55,height=1.55)
nut<-read.csv(file.path(p,'18_nutrition_four_state_descriptive.csv'));nv<-c('BMI','albumin','vitD','risk','LBXSCU','LBXSSE','LBXSZN','LBXSIR','URXUIO');nl<-c('BMI\nkg/m²','Albumin\ng/dL','25(OH)D\nnmol/L','Low-BMI / weight-loss\nproxy, %','Copper, serum\nµg/dL','Selenium, serum\nµg/L','Zinc, serum\nµg/dL','Iron, serum\nµg/dL','Iodine, urine\nµg/L');gs<-c('Q0T0','Q1T0','Q0T1','Q1T1');nut$row_z<-ave(nut$value,nut$variable,FUN=function(z)(z-mean(z))/sd(z));stopifnot(max(abs(nut$row_z))<2);nut$state<-factor(states[match(nut$group,gs)],levels=states);nut$indicator<-factor(nl[match(nut$variable,nv)],levels=rev(nl));val<-ifelse(nut$variable=='risk',100*nut$value,nut$value);nut$cell<-paste0(ifelse(nut$variable=='albumin',sprintf('%.2f',val),sprintf('%.1f',val)),'\nn=',nut$n)
pn<-ggplot(nut,aes(state,indicator,fill=row_z))+geom_tile(colour='white',linewidth=.7)+geom_text(aes(label=cell),size=2.45,lineheight=1.12,colour=ink)+scale_fill_gradient2(low=blue,mid='white',high=orange,limits=c(-2,2),breaks=c(-2,0,2),name='Within-row standardization')+scale_x_discrete(position='top',expand=c(0,0))+scale_y_discrete(expand=c(0,0))+labs(x=NULL,y=NULL)+theme_minimal(base_family='Arial',base_size=8)+theme(panel.grid=element_blank(),axis.text.y=element_text(size=7.5,colour=ink),axis.text.x=element_text(size=8,colour=ink),legend.position='bottom',legend.title=element_text(size=7),legend.text=element_text(size=6.5),legend.key.width=unit(.7,'cm'),plot.margin=margin(0,5,0,0))
ggsave(file.path(o,'Figures/Figure1_C_nutrition.svg'),pn,width=4.55,height=4.65)
write.csv(st,file.path(p,'Figure1_four_state_counts.csv'),row.names=FALSE);write.csv(nut,file.path(p,'Figure1_nutrition_display.csv'),row.names=FALSE)
# Figure 2: linked angular columns, complete exposure screen and all 34 lipid tracks.
x<-read.csv(file.path(p,'06_augmented_outcome_screen_188.csv'));r<-read.csv(file.path(p,'05_full_spectrum_primary_6392.csv'));family<-sort(unique(x$family));x<-x[order(match(x$family,family),x$variable),];x$i<-seq_len(nrow(x));x$a<-pi/2-2*pi*(x$i-.5)/188
v<-read.csv(file.path(b,'IJHEH_Exposure_Nutrition_Phenotype_20261118/Source_data/Figure2_track_key_34.csv'))$variable;stopifnot(length(v)==34,nrow(r)==6392,nrow(x)==188)
r$i<-match(r$variable,x$variable);r$track<-match(r$metabolite,v);r$a<-x$a[r$i];r$rad<-2.05+.080*(r$track-.5);stopifnot(all(!is.na(r$i)),all(!is.na(r$track)))
r$col<-colour(ifelse(r$status=='ok',asinh(r$beta/.1),NA),asinh(1.7/.1));r$col[r$status!='ok']<-'#D0D0D0';stopifnot(max(abs(r$beta[r$status=='ok']))<1.7)
inner<-do.call(rbind,lapply(seq_len(nrow(r)),function(j){z<-arc(pi/2-2*pi*(r$i[j]-1)/188,pi/2-2*pi*r$i[j]/188,2.05+.080*(r$track[j]-1),2.05+.080*r$track[j],j);z$col<-r$col[j];z}))
x$col<-colour(sign(x$b)*(-log10(x$q_188)),2.4);x$col[x$status=='unstable']<-'#888888';x$col[x$status!='ok'&x$status!='unstable']<-'#D3D3D3';outer<-do.call(rbind,lapply(1:188,function(j){z<-arc(pi/2-2*pi*(j-1)/188,pi/2-2*pi*j/188,4.9,5.16,j);z$col<-x$col[j];z}))
bands<-nodes<-branches<-list()
for(j in seq_along(family)){ii<-which(x$family==family[j]);aa<-pi/2-2*pi*c(min(ii)-1,max(ii))/188;am<-mean(aa);z<-arc(aa[1],aa[2],5.22,5.36,j);z$col<-if(j%%2)'#D8E4E9'else'#E2E4E6';bands[[j]]<-z;nodes[[j]]<-data.frame(family=family[j],x=1.2*cos(am),y=1.2*sin(am),lx=5.61*cos(am),ly=5.61*sin(am),id=sprintf('%02d',j),n=length(ii));branches[[j]]<-data.frame(x=1.2*cos(am),y=1.2*sin(am),xe=2*cos(x$a[ii]),ye=2*sin(x$a[ii]))}
bands<-do.call(rbind,bands);nodes<-do.call(rbind,nodes);branches<-do.call(rbind,branches)
pc<-ggplot()+geom_segment(data=nodes,aes(x=0,y=0,xend=x,yend=y),colour='#ABB8C1',linewidth=.3)+geom_segment(data=branches,aes(x,y,xend=xe,yend=ye),colour='#D5DDE2',linewidth=.18)+geom_point(data=nodes,aes(x,y),colour='#929CA5',size=.65)+geom_polygon(data=inner,aes(x,y,group=id,fill=col))+geom_polygon(data=outer,aes(x,y,group=id,fill=col),colour='white',linewidth=.08)+geom_polygon(data=bands,aes(x,y,group=id,fill=col),colour='white',linewidth=.2)+scale_fill_identity()+geom_point(data=subset(r,status=='ok'&q_global<.05),aes(rad*cos(a),rad*sin(a)),size=.24,colour='#15232D')+geom_text(data=subset(x,status=='ok'&q_188<.05),aes(5.03*cos(a),5.03*sin(a)),label='*',size=3)+geom_text(data=nodes,aes(lx,ly,label=id),size=2.1,colour=ink)+annotate('label',x=0,y=0,label='188 biomarkers\n20 families\n34 lipid traits',size=2.7,lineheight=1.25,fill='white',colour=ink,linewidth=0)+coord_equal(xlim=c(-5.95,5.95),ylim=c(-5.95,5.95),expand=FALSE,clip='off')+theme_void(base_family='Arial')+theme(plot.margin=margin(3,3,3,3))
key<-function(vv,m,lab,at){d<-data.frame(z=seq(-m,m,length.out=180));d$col<-colour(d$z,m);ggplot(d,aes(z,0,fill=col))+geom_tile(height=.5)+scale_fill_identity()+scale_x_continuous(breaks=vv,labels=at,expand=c(0,0))+labs(x=lab,y=NULL)+theme_classic(base_family='Arial',base_size=6)+theme(axis.text.y=element_blank(),axis.ticks.y=element_blank(),axis.line=element_blank(),axis.title.x=element_text(size=6.4),plot.margin=margin(0,12,0,12))}
keys<-key(c(-2.4,0,2.4),2.4,'Outer ring: signed −log10(q188)',c('−2.4','0','2.4'))|key(asinh(c(-1,-.1,0,.1,1)/.1),asinh(1.7/.1),'Lipid tracks: coefficient (asinh scale)',c('−1','−.1','0','.1','1'))
short<-c('Arsenic species (urine)'='Arsenic, urine','Caffeine metabolites'='Caffeine metabolites','Chlorophenols (pesticide-related, urine)'='Chlorophenols','DEET metabolites (urine)'='DEET metabolites','Essential trace elements (serum)'='Essential elements, serum','Iodine (urine)'='Iodine, urine','Mercury species (blood)'='Mercury species, blood','Metals (blood)'='Metals, blood','Metals (urine)'='Metals, urine','Organophosphate flame-retardant metabolites (urine)'='OP flame retardants','Organophosphate pesticide metabolites (urine)'='OP pesticides','PAH metabolites (urine)'='PAH metabolites','PFAS (serum)'='PFAS','Perchlorate/nitrate/thiocyanate (urine)'='Perchlorate / nitrate / SCN','Phenols and parabens (urine)'='Phenols / parabens','Phthalate/plasticizer metabolites (urine)'='Phthalates / plasticizers','Pyrethroid/herbicide/OP metabolites (urine)'='Pyrethroid / herbicide / OP','Tobacco smoke biomarkers'='Tobacco biomarkers','VOC metabolites (urine)'='VOC metabolites, urine','VOCs (blood)'='VOCs, blood')[family];stopifnot(!anyNA(short));legend<-ggdraw()
for(j in seq_along(family)){co<-(j-1)%/%7;rr<-(j-1)%%7;legend<-legend+draw_label(sprintf('%02d %s (%d)',j,short[j],nodes$n[j]),x=.006+co*.333,y=.95-rr*.137,hjust=0,size=6.1,fontfamily='Arial')}
tk<-ggdraw();for(j in 1:34){co<-(j-1)%/%7;rr<-(j-1)%%7;tk<-tk+draw_label(paste0(j,': ',sub('^LBX','',sub('^fa_','',v[j]))),x=.01+co*.20,y=.95-rr*.14,hjust=0,size=5.7,fontfamily='Arial')}
fig2<-pc/keys/legend/tk+plot_layout(heights=c(7.2,.48,1.05,.8));savefig(fig2,'Figure2_full_exposome_circular',7.2,9.53)
write.csv(x,file.path(p,'Figure2_188_shared_angular_order.csv'),row.names=FALSE);write.csv(r,file.path(p,'Figure2_6392_linked_cells.csv'),row.names=FALSE);write.csv(nodes,file.path(p,'Figure2_20_family_key.csv'),row.names=FALSE);write.csv(data.frame(track=1:34,variable=v),file.path(p,'Figure2_34_track_key.csv'),row.names=FALSE)
# Figure 3: all 34 outcome estimates in a circular forest, with a common log-OR radial axis.
d<-read.csv(file.path(p,'Figure3_all_34_discordance.csv'));d<-d[match(v,d$metabolite),];stopifnot(nrow(d)==34,all(is.finite(d$OR)),all(d$OR_low>0));d$group<-c(rep('SFA',11),rep('MUFA',6),rep('n-3',5),rep('n-6',7),'ET1',rep('Modules',4));d$groupid<-match(d$group,unique(d$group));d$i<-1:34;d$angle<-72-(d$i-.5)*9-(d$groupid-1)*3;d$a<-d$angle*pi/180
rad<-function(z)2.4+.8*log2(z);d$r<-rad(d$OR);d$rl<-rad(d$OR_low);d$rh<-rad(d$OR_high);stopifnot(all(d$rl>rad(.25)),all(d$rh<rad(4)));d$col<-ifelse(d$OR<1,blue,orange);d$shape<-ifelse(d$layer=='individual',1,0);d$lab<-ifelse(d$layer=='individual',sub('  \\(n=', ' n=',sub('\\)$','',d$label)),paste0(sub('^fa_','',d$metabolite),' n=',d$n));d$left<-cos(d$a)<0;d$rot<-ifelse(d$left,d$angle+180,d$angle);d$hjust<-ifelse(d$left,1,0)
circles<-do.call(rbind,lapply(c(.25,.5,1,2,4),function(z){aa<-seq(0,2*pi,length.out=600);data.frame(x=rad(z)*cos(aa),y=rad(z)*sin(aa),OR=z)}));caps<-do.call(rbind,lapply(1:34,function(j){z<-d[j,];rr<-c(z$rl,z$rh);do.call(rbind,lapply(1:2,function(k){aa<-z$a+c(-.008,.008);data.frame(x=rr[k]*cos(aa),y=rr[k]*sin(aa),id=paste(j,k))}))}));gb<-gl<-list()
for(j in seq_along(unique(d$group))){ii<-which(d$groupid==j);aa<-(c(d$angle[min(ii)]+4.5,d$angle[max(ii)]-4.5))*pi/180;z<-arc(aa[1],aa[2],3.92,4.04,j);z$col<-if(j%%2)'#D8E4E9'else'#E3E5E6';gb[[j]]<-z;am<-mean(aa);gl[[j]]<-data.frame(x=3.76*cos(am),y=3.76*sin(am),label=unique(d$group[ii]),angle=if(cos(am)<0)am*180/pi+180 else am*180/pi)};gb<-do.call(rbind,gb);gl<-do.call(rbind,gl)
forest<-ggplot()+geom_path(data=subset(circles,OR!=1),aes(x,y,group=OR),colour='#E0E5E8',linewidth=.3)+geom_path(data=subset(circles,OR==1),aes(x,y),colour='#7D8993',linewidth=.5,linetype=2)+geom_segment(data=d,aes(x=.78*cos(a),y=.78*sin(a),xend=4.04*cos(a),yend=4.04*sin(a)),colour='#EDF0F2',linewidth=.2)+geom_polygon(data=gb,aes(x,y,group=id,fill=col))+scale_fill_identity()+geom_segment(data=d,aes(x=rl*cos(a),y=rl*sin(a),xend=rh*cos(a),yend=rh*sin(a),colour=col),linewidth=.65)+geom_path(data=caps,aes(x,y,group=id),colour='#6B7883',linewidth=.35)+geom_point(data=d,aes(r*cos(a),r*sin(a),colour=col,shape=shape),size=2.1,stroke=.65)+scale_colour_identity()+scale_shape_identity()+geom_text(data=d,aes(x=4.2*cos(a),y=4.2*sin(a),label=lab,angle=rot,hjust=hjust),size=2.35,colour=ink)+geom_text(data=gl,aes(x,y,label=label,angle=angle),size=2.1,colour='#5A6975')+geom_segment(aes(x=0,y=rad(.25),xend=0,yend=rad(4)),colour='#83909A',linewidth=.3)+geom_text(data=data.frame(OR=c(.25,.5,1,2,4)),aes(x=-.12,y=rad(OR),label=OR),hjust=1,size=2.25,colour=ink)+annotate('text',x=0,y=4.27,label='OR (log scale)',size=2.4,colour=ink)+annotate('text',x=0,y=0,label='QFT-only / TST-only\nOR per SD\nlog2 fatty acid',size=2.5,lineheight=1.25,colour=ink)+coord_equal(xlim=c(-6.15,6.15),ylim=c(-6.15,6.15),expand=FALSE,clip='off')+theme_void(base_family='Arial')+theme(plot.margin=margin(6,7,6,7))
legend3<-ggdraw()+draw_label('○ Individual fatty acids (30)    □ Modules (4)',.5,.72,size=7,fontfamily='Arial')+draw_label('Blue: OR < 1     Orange: OR > 1     Bars: pointwise 95% CI',.5,.30,size=7,fontfamily='Arial')
fig3<-forest/legend3+plot_layout(heights=c(7.2,.5));savefig(fig3,'Figure3_circular_forest',7.2,7.7);write.csv(d,file.path(p,'Figure3_circular_forest_34.csv'),row.names=FALSE)
